import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{matchingRule,movementResult}from'../core.js';import{matchingPhotographs}from'../photographs.js';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),rules=read('research-updates-20261008.json').filter(x=>['A17350','AB3112','E76325'].includes(x.baseReference)),photos=read('photographs.json').photographs.filter(x=>x.id.startsWith('breitling-a17350-20261026-'));
test('Breitling model guidance keeps branded and supplier calibres distinct',()=>{assert.equal(rules.length,3);for(const[r,c]of [['A17350','B17'],['AB3112','B31'],['AB3112241B1A1','B31'],['E76325','Breitling 76']])assert.equal(movementResult(matchingRule(rules,'Breitling',r),c).level,'match');assert.equal(movementResult(matchingRule(rules,'Breitling','A17350'),'2824-2').level,'caution');assert.equal(movementResult(matchingRule(rules,'Breitling','AB3112'),'B20').level,'caution');assert.ok(matchingRule(rules,'Breitling','AB3112').manualReview);for(const r of ['A17050','A173500','AB3112241B1S1','AB3111','UB3112','E76321'])assert.equal(matchingRule(rules,'Breitling',r),null);});
test('Colt exterior photographs remain representative and do not fill a movement gap',()=>{assert.equal(photos.length,3);assert.ok(photos.every(x=>x.category!=='movement'));assert.ok(matchingPhotographs(photos,'Breitling','A17350').every(x=>x.matchScope==='representative variant'));assert.equal(matchingPhotographs(photos,'Breitling','A17350',{externalOnly:true}).length,3);for(const r of ['A17350X','AB3112','E76325'])assert.equal(matchingPhotographs(photos,'Breitling',r).length,0);});
test('Transocean saved supplier marking remains evidence-needed',()=>{const r=read('research-queue-breitling-next-20261026-sources.json').records.find(x=>x.reference==='A41310');assert.equal(r.decision,'needs_evidence');assert.match(r.conclusion,/do not silently equate 2892/);assert.equal(rules.find(x=>x.baseReference==='A41310'),undefined);});
